import glob

counts = {}
for path in glob.glob("tickets/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        next(f)
        for line in f:
            queue = line.strip().split(",")[0]
            counts[queue] = counts.get(queue, 0) + 1
for queue in sorted(counts):
    print(f"{queue} {counts[queue]}")
